    UNION ALL SELECT 15 AS step_order_index, 75 AS order_index, 'O2HIGH_Flow_Ramp' AS alias, '0' AS value
    UNION ALL SELECT 15 AS step_order_index, 76 AS order_index, 'N2_Flow_Set' AS alias, '10000' AS value
    UNION ALL SELECT 15 AS step_order_index, 77 AS order_index, 'N2_Flow_Ramp' AS alias, '0' AS value
) p
JOIN step st
  ON st.recipe_id = @recipe_id
 AND st.code = CONCAT('STEP_', LPAD(p.step_order_index, 2, '0'))
JOIN parameter_definition pd
  ON pd.step_type = 'STEP'
 AND pd.alias = p.alias
LEFT JOIN parameter_option po_match
  ON po_match.definition_id = pd.id
 AND (
       po_match.label = p.value
    OR po_match.code = p.value
    OR po_match.code = UPPER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(p.value), ' ', '_'), '-', '_'), '/', '_'), ':', '_'))
    OR UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(po_match.label), ' ', ''), '-', ''), '/', ''), ':', ''), '''', ''), '_', '')) = UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(p.value), ' ', ''), '-', ''), '/', ''), ':', ''), '''', ''), '_', ''))
    OR UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(po_match.code), ' ', ''), '-', ''), '/', ''), ':', ''), '''', ''), '_', '')) = UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(p.value), ' ', ''), '-', ''), '/', ''), ':', ''), '''', ''), '_', ''))
 )
LEFT JOIN step_parameter sp
  ON sp.step_id = st.id
 AND sp.parent_order_scope = 0
 AND sp.definition_id = pd.id
WHERE sp.id IS NULL
  AND (pd.value_type <> 'ENUM' OR po_match.id IS NOT NULL);

SELECT ROW_COUNT() AS inserted_step_params;
SELECT COUNT(*) AS total_steps FROM step WHERE recipe_id = @recipe_id AND step_kind = 'STEP';
SELECT COUNT(*) AS total_step_params FROM step_parameter sp JOIN step st ON st.id = sp.step_id WHERE st.recipe_id = @recipe_id AND st.step_kind = 'STEP';

